#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's quoting undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"; fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line). Idempotent. Creates ENV_FILE at mode 0600; writes through a symlink
# and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: CARTO basemaps API key → GitHub secret + local dart-define file.
# ──────────────────────────────────────────────────────────────────────────
#
# Run from any checkout:  just carto-key   (or tool/carto_key.sh)
#
# The key never touches the screen, argv or git: it is read hidden, piped to
# `gh secret set` on stdin, handed to curl via a stdin config, and written to
# the gitignored dart_defines.local.json (mode 0600) in this checkout and in
# the main checkout, which release builds come from.

DEFINES_NAME=dart_defines.local.json
REPO_ROOT=$(git rev-parse --show-toplevel)
# The first `git worktree list` entry is the main checkout.
MAIN_ROOT=$(git worktree list --porcelain | sed -n '1s/^worktree //p')
TILE_PATH=rastertiles/voyager_nolabels/3/4/2.png

# tile_etag [KEY]: ETag of one CARTO tile, fetched with KEY if given. The key
# goes to curl on stdin so it never shows up in argv.
tile_etag() {
  local url="https://a.basemaps.cartocdn.com/$TILE_PATH"
  # URL-encoding also keeps any " or \ out of the curl config line.
  [[ -n "${1:-}" ]] && url+="?key=$(CARTO_API_KEY="$1" python3 -c \
    'import os, urllib.parse; print(urllib.parse.quote_plus(os.environ["CARTO_API_KEY"]))')"
  printf 'url = "%s"\n' "$url" \
    | curl -sS -K - -o /dev/null -D - \
    | tr -d '\r' | sed -n 's/^etag: *//Ip' | tr -d '"'
}

# write_defines FILE KEY: (over)writes FILE as {"CARTO_API_KEY": KEY}, 0600.
write_defines() {
  (umask 077 && CARTO_API_KEY="$2" python3 -c \
    'import json, os, sys; json.dump({"CARTO_API_KEY": os.environ["CARTO_API_KEY"]}, sys.stdout, indent=2); print()' \
    > "$1")
  chmod 600 "$1"
  printf '  %s✓ wrote%s CARTO_API_KEY → %s\n' "$GREEN" "$RESET" "$1"
}

TOTAL_STAGES=5

banner "CARTO basemaps API key"

# ──────────────────────────────────────────────────────────────────────────
stage "Pick the tier"
say "CARTO now needs a key on every tile; without one each tile is an"
say "\"API KEY REQUIRED\" watermark, which is why the map is blank."
say ""
say "The key is free either way — the request form only asks whether the"
say "use is commercial, and that sets the free monthly allowance:"
step "Non-commercial: free up to 5M requests/month. CARTO's examples are"
note "    personal, research, teaching and non-profit use. Over the limit,"
note "    they say to get in touch and they normally raise it at no charge."
step "Commercial: free up to 1M requests/month, then paid plans from \$500/mo."
say ""
say "What we know about Walkable (docs/store-listing.md): free on Play, no ads,"
say "no in-app purchases, no accounts, a personal project. That reads as"
say "non-commercial by CARTO's examples — but it's your call, and CARTO's"
say "Basemaps terms are the authority. You can ask support to change it later."
pause "Decided? Press Enter to request the key"

# ──────────────────────────────────────────────────────────────────────────
stage "Request the key"
# Re-run (e.g. key rotation): offer the key already stored here.
CARTO_API_KEY=""
if [[ -f "$REPO_ROOT/$DEFINES_NAME" ]] && ! confirm "A key is already stored in $DEFINES_NAME. Replace it with a new one?"; then
  CARTO_API_KEY=$(python3 -c 'import json, sys; print(json.load(open(sys.argv[1])).get("CARTO_API_KEY", ""))' "$REPO_ROOT/$DEFINES_NAME")
fi
if [[ -z "$CARTO_API_KEY" ]]; then
open_url "https://carto.com/basemaps/apikey"
step "Click \"Request a key\" (if the form doesn't load, use"
note "    https://dashboard.basemaps.carto.com instead)."
step "Enter your e-mail and answer the commercial-use question as decided."
step "Open the e-mail CARTO sends (\"in your inbox in a minute\") and click"
note "    the sign-in link — no password, the link is the login."
step "In the Basemaps dashboard, copy the API key."
say ""
ask_secret CARTO_API_KEY "Paste the key (hidden):"
fi
[[ -n "$CARTO_API_KEY" ]] || { warn "no key entered; re-run when you have it"; exit 1; }

# ──────────────────────────────────────────────────────────────────────────
stage "Check the key serves real tiles"
say "Fetching one tile without and with the key, comparing ETags."
keyless=$(tile_etag || true)
keyed=$(tile_etag "$CARTO_API_KEY" || true)
note "without key: ${keyless:-<none>}"
note "with key:    ${keyed:-<none>}"
if [[ -z "$keyed" || "$keyed" == wm-* ]]; then
  warn "the keyed tile is still the watermark (or the request failed)."
  warn "Check you copied the whole key; a fresh key may take a minute."
  confirm "Store it anyway?" || exit 1
else
  printf '  %s✓ real map tile%s — the key works\n' "$GREEN" "$RESET"
fi
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Store the key"
say "GitHub Actions secret CARTO_API_KEY (for the tag-triggered release workflow), plus the"
say "gitignored $DEFINES_NAME that \`just apk\` / \`just bundle\` / fastlane read."
say ""
set_secret CARTO_API_KEY "$CARTO_API_KEY"
write_defines "$REPO_ROOT/$DEFINES_NAME" "$CARTO_API_KEY"
if [[ -n "$MAIN_ROOT" && "$MAIN_ROOT" != "$REPO_ROOT" ]]; then
  write_defines "$MAIN_ROOT/$DEFINES_NAME" "$CARTO_API_KEY"
fi
# Also exclude it repo-wide (shared by every worktree), so checkouts whose
# .gitignore predates the entry can't commit it either.
exclude="$(git rev-parse --path-format=absolute --git-common-dir)/info/exclude"
mkdir -p "$(dirname "$exclude")"
grep -qxF "/$DEFINES_NAME" "$exclude" 2>/dev/null || printf '/%s\n' "$DEFINES_NAME" >> "$exclude"
for root in "$REPO_ROOT" "$MAIN_ROOT"; do
  if git -C "$root" check-ignore -q "$DEFINES_NAME"; then
    note "$root/$DEFINES_NAME is git-ignored."
  else
    warn "$DEFINES_NAME is NOT ignored in $root — don't commit it."
    SKIPPED+=("make git ignore $root/$DEFINES_NAME")
  fi
done
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Key restrictions (read, then skip for now)"
say "The dashboard can restrict a key two ways:"
step "Website restrictions match the Referer header. A native Android app"
note "    sends no Referer, so these don't apply to Walkable — don't add one,"
note "    it would protect nothing."
step "Mobile-app restrictions require the X-Android-Package and"
note "    X-Android-Cert headers on every tile request. Walkable doesn't send"
note "    them yet, so enabling one now would blank the map again."
say ""
say "Also worth knowing: the key ships inside a public APK and repo, and those"
say "headers are easy to copy, so a restriction only deters casual reuse. The"
say "real backstop is the monthly cap. Leave restrictions off for now; sending"
say "the headers (dk.alexanderlhc.walkable + the Play app-signing cert SHA-1) is a"
say "follow-up if the dashboard ever shows usage that isn't Walkable's."
pause "Press Enter to finish"

finish
note "Build a release with the key: just bundle   (or: just apk)"
